    /** Flattened label lookup, used by topbar.blade.php to show the current page's title without a second copy of every label. */
    public static function currentLabel(): ?string
    {
        $current = request()->route()?->getName();

        foreach (self::groups() as $items) {
            foreach ($items as $item) {
                if ($item['route'] === $current) {
                    return $item['label'];
                }
            }
        }

        return null;
    }
